-- Owner-only, synthetic packing configuration. No contact or provider operations.
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000001","aal":"aal1"}',true);
select pg_temp.assert_true(public.read_packing_rules('20000000-0000-4000-8000-000000000001')->'rules'='[]'::jsonb,'no unapproved defaults');
select public.approve_packing_rule('20000000-0000-4000-8000-000000000001','Lawn care','Mow, trim and blow',0,'[{"name":"Mower","quantity":1,"unit":"each","consumed":false}]','packing-approve-key-01');
select public.approve_packing_rule('20000000-0000-4000-8000-000000000001','Lawn care','Mow, trim and blow',0,'[{"name":"Mower","quantity":1,"unit":"each","consumed":false}]','packing-approve-key-01');
select pg_temp.assert_true(jsonb_array_length(public.read_packing_rules('20000000-0000-4000-8000-000000000001')->'rules')=1,'retry saves one rule');
select pg_temp.assert_true((select count(*)=1 from public.audit_events where action='packing.rule_approved'),'retry saves one audit');
do $$begin begin perform public.approve_packing_rule('20000000-0000-4000-8000-000000000001','Lawn care','Mow, trim and blow',0,'[]','packing-approve-key-01');raise exception 'TEST FAILED changed replay';exception when raise_exception then if sqlerrm<>'IDEMPOTENCY_CONFLICT' then raise;end if;end;end$$;
do $$begin begin perform public.approve_packing_rule('20000000-0000-4000-8000-000000000001','Lawn care','Mow, trim and blow',0,'[]','packing-stale-key-01');raise exception 'TEST FAILED stale version';exception when raise_exception then if sqlerrm<>'STALE_REVISION' then raise;end if;end;end$$;
select public.approve_packing_rule('20000000-0000-4000-8000-000000000001','Lawn care','Mow, trim and blow',1,'[{"name":" Mower ","quantity":2,"unit":"Each","consumed":false}]','packing-edit-key-001');
select public.approve_packing_rule('20000000-0000-4000-8000-000000000001','Home','Door check',0,'[]','packing-empty-key-001');
select pg_temp.assert_true(jsonb_array_length(public.read_packing_rules('20000000-0000-4000-8000-000000000001','[{"service":"Home","task":"Door check"}]')->'rules')=1,'daily query returns only selected task rules');
select pg_temp.assert_true(public.read_packing_rules('20000000-0000-4000-8000-000000000001','[]')->'rules'='[]'::jsonb,'empty day reads no unrelated rules');
do $$begin begin perform public.approve_packing_rule('20000000-0000-4000-8000-000000000001','Home','Trim' ,0,'[{"name":"Rake","quantity":1,"unit":"each","consumed":false},{"name":" RAKE ","quantity":2,"unit":"each","consumed":false}]','packing-duplicate-01');raise exception 'TEST FAILED duplicate tools';exception when raise_exception then if sqlerrm<>'DUPLICATE_EQUIPMENT' then raise;end if;end;end$$;
do $$declare bad jsonb;begin
 foreach bad in array array['[null]'::jsonb,'[{"name":"Mower","quantity":0,"unit":"each","consumed":false}]'::jsonb,'[{"name":"Mower","quantity":1,"unit":"each","consumed":false,"approved":true}]'::jsonb] loop
  begin perform public.approve_packing_rule('20000000-0000-4000-8000-000000000001','Home','Invalid',0,bad,'packing-invalid-key-01');raise exception 'TEST FAILED invalid equipment';exception when raise_exception then if sqlerrm<>'VALIDATION' then raise;end if;end;
 end loop;
end$$;
reset role;
select pg_temp.assert_true((select count(*)=2 from private.packing_rule_versions where service_name='Lawn care'),'immutable rule versions retained');
select pg_temp.assert_true((select items->0->>'quantity'='1' from private.packing_rule_versions where service_name='Lawn care' and revision=1),'old quantity unchanged');
select pg_temp.assert_true((select count(*)=3 from public.audit_events a join private.packing_rules r on r.organization_id=a.organization_id and r.id=a.object_id where a.action='packing.rule_approved'),'audit points to the exact rule');
select pg_temp.assert_true(not has_table_privilege('authenticated','private.packing_rules','SELECT'),'clients cannot bypass packing RPC');
select pg_temp.assert_true(not has_table_privilege('service_role','private.packing_rules','UPDATE'),'no generic worker edit grant');
select pg_temp.assert_true(not has_function_privilege('anon','public.approve_packing_rule(uuid,text,text,integer,jsonb,text)','EXECUTE'),'anonymous approval denied');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000002","session_id":"10000000-0000-4000-8000-000000000002","aal":"aal1"}',true);
do $$begin begin perform public.read_packing_rules('20000000-0000-4000-8000-000000000001');raise exception 'TEST FAILED tenant read';exception when insufficient_privilege then null;end;begin perform public.approve_packing_rule('20000000-0000-4000-8000-000000000001','Home','Door check',1,'[]','packing-cross-key-01');raise exception 'TEST FAILED tenant edit';exception when insufficient_privilege then null;end;end$$;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000003","session_id":"10000000-0000-4000-8000-000000000003","aal":"aal1"}',true);
do $$begin begin perform public.read_packing_rules('20000000-0000-4000-8000-000000000001');raise exception 'TEST FAILED customer read';exception when insufficient_privilege then null;end;end$$;
reset role;
insert into private.platform_administrators(user_id) values('00000000-0000-4000-8000-000000000004');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000004","session_id":"10000000-0000-4000-8000-000000000004","aal":"aal1"}',true);
select pg_temp.assert_true(private.platform_admin(),'platform metadata authorization is valid');
do $$begin begin perform public.read_packing_rules('20000000-0000-4000-8000-000000000001');raise exception 'TEST FAILED platform tenant read';exception when insufficient_privilege then null;end;end$$;
reset role;
update public.memberships set revoked_at=now() where user_id='00000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000001","aal":"aal1"}',true);
do $$begin begin perform public.approve_packing_rule('20000000-0000-4000-8000-000000000001','Lawn care','Mow, trim and blow',0,'[{"name":"Mower","quantity":1,"unit":"each","consumed":false}]','packing-approve-key-01');raise exception 'TEST FAILED revoked replay';exception when insufficient_privilege then null;end;end$$;
reset role;
update public.memberships set revoked_at=null where user_id='00000000-0000-4000-8000-000000000001';
update auth.sessions set not_after=now()-interval '1 second' where user_id='00000000-0000-4000-8000-000000000001';
set local role authenticated;
do $$begin begin perform public.read_packing_rules('20000000-0000-4000-8000-000000000001');raise exception 'TEST FAILED expired session';exception when insufficient_privilege then null;end;end$$;
reset role;
rollback;
